contract.code:
Run = { runId, sessionId, askedBy, asked, status: RunStatus, runBy?, steers: Int, result? }
SessionView = { sessionId, planId, title, startedBy, status: 'open' | 'ended',
                participants: ParticipantId[], runs: Run[] }

sessionCommand(planId: string, type: string, data: unknown, by: string): Promise<{ events: Recorded[] } | Rejection>
sessionList(): Promise<SessionView[]>
sessionView(sessionId: string): Promise<SessionView | undefined>
// StartSession gets planId and a fresh sessionId here; every socket gets { type: 'session', events }

POST /plans/:planId/sessions            { type, data } → 201 { events } | 401 | 409 { rejected }
GET  /plans/:planId/sessions            → { sessions: SessionView[] }
GET  /plans/:planId/sessions/:sessionId → SessionView | 404 { error: 'no such session' }

components.css:
.panel { max-width: 380px; border: 1px solid var(--line); border-radius: var(--radius-lg); padding: 20px; font-family: var(--font); display: flex; flex-direction: column; gap: 16px; }
h2 { margin: 0; font-size: 18px; font-weight: 600; }
p { margin: 0; }
.muted { font-size: 14px; color: var(--muted); }
.meta { font-size: 12px; color: var(--muted); }
.chips { display: flex; flex-wrap: wrap; gap: 8px; list-style: none; margin: 0; padding: 0; }
.chips button { font: inherit; font-size: 12px; padding: 4px 12px; border: 1px solid var(--line); border-radius: 999px; background: var(--surface); color: var(--ink); }
.chips button[aria-pressed=true] { border-color: var(--ink); font-weight: 600; }
ol { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 12px; }
.asked { font-size: 14px; }
.who { display: block; font-size: 12px; color: var(--muted); }
.status { margin-top: 4px; font-size: 12px; color: var(--muted); }
.result { margin-top: 6px; font-size: 14px; border-left: 2px solid var(--line); padding-left: 10px; }
form { display: flex; gap: 8px; }
form.start { border-top: 1px solid var(--line); padding-top: 16px; }
input { flex: 1; min-width: 0; font: inherit; font-size: 14px; padding: 8px 12px; border: 1px solid var(--line); border-radius: var(--radius-md); background: var(--surface); color: var(--ink); }
button { font: inherit; font-size: 14px; font-weight: 600; padding: 8px 14px; border: 1px solid var(--line); border-radius: var(--radius-md); background: var(--surface); color: var(--ink); }
button.primary { background: var(--accent); border-color: transparent; color: #fff; }
button.link { align-self: flex-start; padding: 0; border: 0; background: none; font-size: 12px; font-weight: 400; color: var(--muted); text-decoration: underline; }
.alert { border: 1px solid var(--alertLine); background: var(--alert); color: var(--warn); border-radius: var(--radius-md); padding: 6px 10px; font-size: 13px; }
a { color: inherit; }

