contract.code:
type SessionsApi = {
  list(planId: string): Promise<SessionViewLite[]>;
  command(planId: string, type: string, data: Record<string, unknown>): Promise<{ ok: boolean; rejected?: string }>;
};
type Answerer = { answer(sessionId: string, runId: string, asked: string): Promise<string> };
tick(planId: string, me: string, api: SessionsApi, brain: Answerer, log?: (line: string) => void): Promise<number>

openBrain(dbPath: string, log?: (line: string) => void): Promise<Brain>
type Brain = { model: string; answer(sessionId, runId, asked): Promise<string>; close(): Promise<void> }
// on open: harness.resume(); per Run: submit({ type: 'input', content: asked, requestId: runId })
